// ---- Preloader: pulls every image into the browser cache in the background (current tab first) so tabs/search/picker show instantly.
const PRELOAD=true, WARM_CONC=3;
const WARM_SEEN=new Set(); let warmQ=[], warmRun=0;
function warmPump(){while(warmRun<WARM_CONC&&warmQ.length){const u=warmQ.shift();warmRun++;const im=new Image(),done=()=>{warmRun--;warmPump()};im.referrerPolicy='no-referrer';im.decoding='async';try{im.fetchPriority='low'}catch{}im.onload=im.onerror=done;im.src=u}}
