 const queued=front?new Set(warmQ):null,add=[];
 for(const u of urls){if(!u)continue;if(!WARM_SEEN.has(u)){WARM_SEEN.add(u);add.push(u)}else if(front&&queued.has(u))add.push(u)}   // front: also pull already-queued images to the head
