function specialExtras(d){if(!d)return 0;const base=['shadow','purified','lucky','perfect','nundo','mega','dynamax','gigantamax','xxl','xxs','costumeOwned'];const shinyBase=base.map(k=>'shiny_'+k);let n=0;for(const k of Object.keys(d)){if(!d[k])continue;if(base.includes(k)||shinyBase.includes(k))n++;else if(k.startsWith('mega_')||k.startsWith('shiny_mega_')||k.startsWith('bg_')||k.startsWith('shiny_bg_')||k.startsWith('cos_')||k.startsWith('shiny_cos_'))n++}n+=(d.costumes||[]).filter(x=>x.caught||x.shiny).length;return n}
