  $('#pairCreate').textContent=has?'Save':'Create';
  const n=$('#pairNote');n.value=target.note||'';$('#pairNoteN').textContent=200-n.value.length;
  m.classList.remove('closing');m.hidden=false;document.body.classList.add('pairopen');syncAll();
