async function init(){
 sprites=cloneSprites(DEFAULT_SPRITES);
 const spP=loadSprites();useEmbedded();
 const gen=document.querySelector('#generation');gens.forEach((g,i)=>{let o=document.createElement('option');o.value=i+1;o.textContent=`Gen ${i+1} · ${g[0]}`;gen.append(o)});
 const ty=document.querySelector('#type');types.forEach(x=>{let o=document.createElement('option');o.value=x;o.textContent=x[0].toUpperCase()+x.slice(1);ty.append(o)});
 document.querySelector('#grid').innerHTML='<i class="skel"></i>'.repeat(14);
 try{
  const CK='goPokedexTracker.cat.v1';let cached=null;try{cached=JSON.parse(localStorage.getItem(CK)||'null')}catch{}
  const getNames=async()=>{if(cached&&Array.isArray(cached.names)&&cached.names.length===1025)return cached.names;const r=await fetch('https://pokeapi.co/api/v2/pokemon?limit=1025');if(!r.ok)throw Error('PokéAPI unavailable');return (await r.json()).results.map(x=>x.name)};
  const _t0=performance.now();const names=await getNames();console.log('[perf] names',Math.round(performance.now()-_t0)+'ms',(cached&&cached.names)?'(cache)':'(PokéAPI)');
  try{if(!(cached&&cached.names))localStorage.setItem(CK,JSON.stringify({names,types:(cached&&cached.types)||{}}))}catch(e){console.warn('[perf] cache not saved',e&&e.name)}
  if(!IMG.idx.size)await spP;   // only wait for the network if there is no built-in sprite list
  const tcache=(cached&&cached.types)||{};
  pokemon=names.map((n,i)=>({id:i+1,name:n.split('-').map(w=>w[0]?.toUpperCase()+w.slice(1)).join('-'),types:tcache[i+1]||[]}));
  {/* do not wipe user progress for species missing from the sprite index — that caused false "unreleased" drops */}
  console.log('[perf] render start',Math.round(performance.now())+'ms since page start');render();setTimeout(()=>{try{pdxSummary()}catch{}},0);
  spP.then(ch=>{if(ch&&document.querySelector('#type'))render();warmEverything()});
  const persist=()=>{try{localStorage.setItem(CK,JSON.stringify({names,types:tcache}))}catch{}};persist();
  const paint=()=>document.querySelectorAll('#grid .card[data-id]').forEach(c=>{const p=pokemon[+c.dataset.id-1],bx=c.querySelector('.types');if(p&&bx&&!bx.children.length&&p.types.length)bx.innerHTML=p.types.map(x=>`<span class="type t-${esc(x)}">${x}</span>`).join('')});
  const need=pokemon.filter(p=>!p.types.length);
  for(let st=0;st<need.length;st+=60){await Promise.all(need.slice(st,st+60).map(async p=>{try{const x=await fetch(`https://pokeapi.co/api/v2/pokemon/${p.id}`);const j=await x.json();p.types=tcache[p.id]=j.types.map(t=>t.type.name)}catch{}}));paint()}
  if(need.length){persist();if(document.querySelector('#type').value!=='all')render()}
 }catch(e){document.querySelector('#grid').innerHTML='<div class="empty">Could not load the Pokédex. Please check your internet connection and refresh this page.</div>';document.querySelector('#shown').textContent='Catalog unavailable'}
 stats()
}
